import{_ as o,o as n,c as r,a7 as i,j as e}from"./chunks/framework.CGOdZqn8.js";const a="/temp/images/FRUC01.png",s="/temp/images/FRUC02.png",g="/temp/images/FRUC03.png",p="/temp/images/SLAM01.png",c="/temp/images/SLAM02.png",l="/temp/images/SLAM03.png",m="/temp/images/GAN01.png",f="/temp/images/GAN02.png",u="/temp/images/DEHAZING01.png",d="/temp/images/DEHAZING02.png",h="/temp/images/MSR01.png",_="/temp/images/MSR02.png",F="/temp/images/MSR03.png",R="/temp/images/3D01.png",S="/temp/images/3D02.png",A="/temp/images/3D03.png",M="/temp/images/CEILING01.png",x="/temp/images/CEILING02.png",N=JSON.parse('{"title":"Research Interests","description":"","frontmatter":{},"headers":[],"relativePath":"research/interests.md","filePath":"research/interests.md","lastUpdated":1793084913000}'),y={name:"research/interests.md"};function D(C,t,w,v,L,I){return n(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="research-interests" tabindex="-1">Research Interests <a class="header-anchor" href="#research-interests" aria-label="Permalink to &quot;Research Interests&quot;">​</a></h1><h2 id="frame-rate-up-conversion-fruc-frame-interpolation" tabindex="-1">Frame Rate Up Conversion (FRUC), Frame Interpolation <a class="header-anchor" href="#frame-rate-up-conversion-fruc-frame-interpolation" aria-label="Permalink to &quot;Frame Rate Up Conversion (FRUC), Frame Interpolation&quot;">​</a></h2><p><strong>FRUC(Frame Rate Up Conversion)</strong> : 영상열에 일정한 주기로 <strong>추가적인 프레임을 삽입</strong> 하여 단위 시간당 <strong>출력되는 프레임의 수를 증가</strong> 시키는 기법이다. 기존의 방법은 움직임 추정 기법에 따라 단방향 움직임 추정(Unilateral Motion Estimation, UME)과 양방향 움직임 추정(Bilateral Motion Estimation, BME)으로 나뉜다. <strong>UME</strong>에서는 정확한 움직임 추정이 가능하나 <strong>overlap과 hole</strong>과 같은 문제점이 존재하고, <strong>BME</strong>에서는 overlap과 hole과 같은 문제는 없지만 <strong>부정확한 움직임 추정으로 인한 화질 저하</strong>가 발생한다. 이러한 문제를 해결하기 위해 <strong>UME와 BME 기법을 동시에 사용하는 Hybrid Bilateral Motion Estimation</strong> 방법을 제안하였다.</p><figure><img src="'+a+'" alt="Fig5-1. Concept of FRUC" style="width:800px;"><figcaption>Fig5-1. Concept of FRUC</figcaption></figure><figure><img src="'+s+'" alt="Fig5-2. 기존 방법과 제안한 방법 성능 비교(주관적 평가)" style="width:600px;"><figcaption>Fig5-2. 기존 방법과 제안한 방법 성능 비교(주관적 평가)</figcaption></figure><figure><img src="'+g+'" alt="Fig5-3. 기존 방법과 제안한 방법 성능 비교(PSNR)" style="width:500px;"><figcaption>Fig5-3. 기존 방법과 제안한 방법 성능 비교(PSNR)</figcaption></figure>',6),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube.com/embed/ojwqIOHIK_w",title:"YouTube video",allow:"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),i('<p style="text-align:center;">Video. 기존 방법(좌), 제안 방법(우)</p><h2 id="visual-odometry-and-slam" tabindex="-1">Visual odometry and SLAM <a class="header-anchor" href="#visual-odometry-and-slam" aria-label="Permalink to &quot;Visual odometry and SLAM&quot;">​</a></h2><p><strong>SLAM(Simultaneous Localization and Mapping)</strong> : 로봇이 자신의 <strong>위치와 주변 지도를 동시에 추정</strong>하는 기법으로, GPS를 사용할 수 없는 환경에서도 동작이 가능하다는 장점이 있다. SLAM은 추적 및 매칭에서 발생하는 오차가 성능에 큰 영향을 미친다. 이러한 문제를 해결하기 위해 <strong>RAFSet SLAM</strong>을 제안하였다.</p><figure><img src="'+p+'" alt="Fig1-1. Concept of RAF(Robust Aged Feature)" style="width:800px;"><figcaption>Fig1-1. Concept of RAF(Robust Aged Feature)</figcaption></figure><figure><img src="'+c+'" alt="Fig1-2. RAFSet SLAM Results" style="width:800px;"><figcaption>Fig1-2. RAFSet SLAM Results</figcaption></figure><figure><img src="'+l+'" alt="Fig1-3. KITTI Visual Odometry 부문 31위 (17.07.13)" style="width:600px;"><figcaption>Fig1-3. KITTI Visual Odometry 부문 31위 (17.07.13)</figcaption></figure><h2 id="딥러닝-적대적-생성-네트워크-gan" tabindex="-1">딥러닝(적대적 생성 네트워크, GAN) <a class="header-anchor" href="#딥러닝-적대적-생성-네트워크-gan" aria-label="Permalink to &quot;딥러닝(적대적 생성 네트워크, GAN)&quot;">​</a></h2><p><strong>GAN(Generative Adversarial Networks)</strong> : 대표적인 **비지도 학습(Unsupervised Learning)**중 하나로 **생성자(Generator)**와 **구별자(Discriminator)**의 **경쟁(Minimax problem)**을 통해 이미지를 생성한다.</p><figure><img src="'+m+'" alt="Fig2-1. Concept of GAN" style="width:800px;"><figcaption>Fig2-1. Concept of GAN</figcaption></figure><figure><img src="'+f+'" alt="Fig2-2. GAN Results" style="width:800px;"><figcaption>Fig2-2. GAN Results</figcaption></figure><h2 id="de-hazing" tabindex="-1">De-Hazing <a class="header-anchor" href="#de-hazing" aria-label="Permalink to &quot;De-Hazing&quot;">​</a></h2><p><strong>De-Hazing</strong> : <strong>안개나 해무, 옅은 구름</strong> 등으로 인해 발생하는 <strong>열화를 개선</strong>하는 기법으로, <strong>기존의 DCP(Dark Channel Prior)</strong> 기반의 알고리즘의 경우 <strong>짙은 안개에 취약</strong>하다는 단점이 있다. 이러한 문제를 해결하기 위해 <strong>HLS 컬러 공간 기반의 안개 제거 기법</strong>을 제안하였다.</p><figure><img src="'+u+'" alt="Fig3-1. Concept of De-Hazing" style="width:800px;"><figcaption>Fig3-1. Concept of De-Hazing</figcaption></figure><figure><img src="'+d+'" alt="Fig3-2. HLS 컬러 기반의 안개 제거 성능 (입력, 출력)" style="width:600px;"><figcaption>Fig3-2. HLS 컬러 기반의 안개 제거 성능 (입력, 출력)</figcaption></figure><h2 id="intensity-enhancement-retinex" tabindex="-1">Intensity Enhancement (Retinex) <a class="header-anchor" href="#intensity-enhancement-retinex" aria-label="Permalink to &quot;Intensity Enhancement (Retinex)&quot;">​</a></h2><p><strong>Intensity Enhancement</strong> : <strong>역광현상</strong>이나 <strong>부족한 광원의 세기</strong>로 인해 발생하는 <strong>열화를 개선</strong>하는 기법으로, 기존의 MSR의 경우 각 채널을 독립적으로 연산하여 원본의 색상 정보를 왜곡하고, 채도가 다소 떨어진다는 단점이 있다. 이러한 문제를 해결하기 위해 **MSRMS(MSR with Modified contrast and Saturation correction)**를 제안하였다.</p><figure><img src="'+h+'" alt="Fig4-1. Concept of MSR" style="width:800px;"><figcaption>Fig4-1. Concept of MSR</figcaption></figure><figure><img src="'+_+'" alt="Fig4-2. Flow chart of MSRMS" style="width:600px;"><figcaption>Fig4-2. Flow chart of MSRMS</figcaption></figure><figure><img src="'+F+'" alt="Fig4-2. MSRMS의 성능 (입력, 출력)" style="width:600px;"><figcaption>Fig4-2. MSRMS의 성능 (입력, 출력)</figcaption></figure><h2 id="_3d-reconstruction-active-stereo-vision" tabindex="-1">3D Reconstruction (Active Stereo Vision) <a class="header-anchor" href="#_3d-reconstruction-active-stereo-vision" aria-label="Permalink to &quot;3D Reconstruction (Active Stereo Vision)&quot;">​</a></h2><p><strong>Active Stereo Vision</strong> : <strong>두 대의 카메라</strong>를 이용하여 깊이 정보를 획득하는 스테레오 비전 기법에 <strong>추가적인 광원을 배치</strong>하여 성능을 향상 시키는 방법이다.</p><figure><img src="'+R+'" alt="Fig6-1. Concept of Active Stereo Vision" style="width:600px;"><figcaption>Fig6-1. Concept of Active Stereo Vision</figcaption></figure><figure><img src="'+S+'" alt="Fig6-2. Depth Map 예시 (입력, 깊이 맵)" style="width:600px;"><figcaption>Fig6-2. Depth Map 예시 (입력, 깊이 맵)</figcaption></figure><figure><img src="'+A+'" alt="Fig6-3. 3D reconstruction results of mask (입력, 3차원 복원)" style="width:600px;"><figcaption>Fig6-3. 3D reconstruction results of mask (입력, 3차원 복원)</figcaption></figure><h2 id="천장-지향-2d-lidar를-이용한-공간-정보-획득-및-위치-추정" tabindex="-1">천장 지향 2D-LiDAR를 이용한 공간 정보 획득 및 위치 추정 <a class="header-anchor" href="#천장-지향-2d-lidar를-이용한-공간-정보-획득-및-위치-추정" aria-label="Permalink to &quot;천장 지향 2D-LiDAR를 이용한 공간 정보 획득 및 위치 추정&quot;">​</a></h2><p><strong>LiDAR(Light Detection and Ranging)</strong> : <strong>빛이 물체에 반사되어 돌아오는 시간</strong>을 이용해 <strong>거리를 측정</strong>하는 센서이다. 2D-LiDAR를 회전하여 3차원 정보를 획득하고, <strong>기존의 3D-LiDAR에 비해 높은 공간해상력을 획득하는 방법</strong>을 제안한다.</p><figure><img src="'+M+'" alt="Fig7-1. 천장 지향 LiDAR 위치 추정 개념" style="width:800px;"><figcaption>Fig7-1. 천장 지향 LiDAR 위치 추정 개념</figcaption></figure><figure><img src="'+x+'" alt="Fig7-2. 벽 추정 결과 및 위치 추정 에러" style="width:500px;"><figcaption>Fig7-2. 벽 추정 결과 및 위치 추정 에러</figcaption></figure>',28)])])}const E=o(y,[["render",D]]);export{N as __pageData,E as default};
